MODE="all"
TARGET=""
while [ $# -gt 0 ]; do
  case "$1" in
    --list) MODE="list" ;;
    --gate) MODE="gate" ;;
    --no-gate) WITH_GATE=0 ;;
    --track) MODE="track"; TARGET="${2:-}"; shift ;;
    --seq) MODE="seq"; TARGET="${2:-}"; shift ;;
    -h|--help) sed -n "2,14p" "$0"; exit 0 ;;
    *) red "unknown argument: $1"; sed -n "2,14p" "$0"; exit 2 ;;
  esac
  shift
done

if [ "$MODE" = "list" ]; then list_targets; exit 0; fi

prepare_env

case "$MODE" in
  all) run_all ;;
  gate) WITH_GATE=1; start_summaries; finish gate ;;
  track)
    case "$TARGET" in
      *) fail "unknown track: '$TARGET' — see the available ones with --list" ;;
    esac ;;
  seq)
    case "$TARGET" in
      T-001) event --type start --scope "seq:T-001"; start_summaries; run_seq_T_001 || true; finish "seq:T-001" ;;
      T-002) event --type start --scope "seq:T-002"; start_summaries; run_seq_T_002 || true; finish "seq:T-002" ;;
      T-003) event --type start --scope "seq:T-003"; start_summaries; run_seq_T_003 || true; finish "seq:T-003" ;;
      T-004) event --type start --scope "seq:T-004"; start_summaries; run_seq_T_004 || true; finish "seq:T-004" ;;
      T-005) event --type start --scope "seq:T-005"; start_summaries; run_seq_T_005 || true; finish "seq:T-005" ;;
      T-006) event --type start --scope "seq:T-006"; start_summaries; run_seq_T_006 || true; finish "seq:T-006" ;;
      T-007) event --type start --scope "seq:T-007"; start_summaries; run_seq_T_007 || true; finish "seq:T-007" ;;
      T-008) event --type start --scope "seq:T-008"; start_summaries; run_seq_T_008 || true; finish "seq:T-008" ;;
      T-009) event --type start --scope "seq:T-009"; start_summaries; run_seq_T_009 || true; finish "seq:T-009" ;;
      T-010) event --type start --scope "seq:T-010"; start_summaries; run_seq_T_010 || true; finish "seq:T-010" ;;
      T-011) event --type start --scope "seq:T-011"; start_summaries; run_seq_T_011 || true; finish "seq:T-011" ;;
      T-012) event --type start --scope "seq:T-012"; start_summaries; run_seq_T_012 || true; finish "seq:T-012" ;;
      T-013) event --type start --scope "seq:T-013"; start_summaries; run_seq_T_013 || true; finish "seq:T-013" ;;
      *) fail "unknown sequential task: '$TARGET' — see the available ones with --list" ;;
